import React, { useEffect } from 'react';
import { Text } from 'react-native';
import { getEmbedding } from './native/FaceEmbed';

const cosineSimilarity = (a, b) => {
  let dot = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
};

export default function App() {
  useEffect(() => {
    async function run() {
      try {
        const base64 = `data:image/jpeg;base64,`;
        const jayam = `data:image/jpeg;base64,`;
        // const jayam = `data:image/jpeg;base64,`;

        const cleanBase64 = base64.replace(/^data:image\/\w+;base64,/, '');
        const cleanJayam = jayam.replace(/^data:image\/\w+;base64,/, '');
        const emb = await getEmbedding(cleanBase64);
        const jayamemb = await getEmbedding(cleanJayam);
        console.log('Embedding:', cosineSimilarity(emb, jayamemb));
      } catch (error) {
        console.error(error);
      }
    }
    run();
  }, []);

  return <Text>Embedding Test</Text>;
}
